// The platform's own message type, declared once as an external type.
// AI/Completions takes an array of exactly this shape.
var messages = new List<ChatMessage>
{
    new ChatMessage() { Role = "system", Content = $"Answer in a {Input.tone} tone." },
    new ChatMessage() { Role = "user", Content = Input.question }
};

return messages.ToArray();

// Every chunk is a serialised completion object; the text lives in
// choices[0].delta.content, the same shape the chat API streams.
var chunks = (List<string>)#Previous;
string answer = "";
foreach (var chunk in chunks)
{
    var piece = new JSON(chunk).choices[0].delta.content as string;
    if (!string.IsNullOrEmpty(piece))
        answer += piece;
}

Logger.LogInformation($"joined {chunks.Count} chunks");
return new AskResult() { question = Input.question, answer = answer };

types.AskResult:
public class AskResult
{
    /* What the caller asked, kept so the answer is self-describing. */
    public string question { get; set; }

    /* The chunks joined back into one text. */
    public string answer { get; set; }
}

